"""YouTube description draft (chapters from the real timeline + required credits)."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
tl=json.loads((ROOT/'data'/'hn_timeline.json').read_text(encoding='utf8'))
def ts(s):s=int(s);return f'{s//60}:{s%60:02d}'
ch=[('本能寺の変 ― 数字で見る夜',tl[0]['start'])]+[(c['title'].split(' / ')[-1] if ' / ' in c['title'] else c['title'],c['start']) for c in tl[1:]]
PART={'a_origin':'【第1部 光秀という人物】','b_peak':'【第2部 1582年の春】','c_ieyasu':'【第3部 運命の五月】','d_depart':'【第4部 六月一日の夜】','f_intro':'【第5部 その頃、各地では】','m_intro':'【第6部 諸説を比べる】','s_intro':'【第7部 史料を読む】'}
ch=[(PART.get(c['key'],'')+n,t_) for (n,t_),c in zip(ch,tl)]
ch=[c for c in ch if c[0]!='出典・制作クレジット']
ch=[(n.replace('この動画のまとめ','この動画のまとめ(山崎の戦いは別の動画で)'),t_) for n,t_ in ch]
L=['# YouTube 投稿用ドラフト\n','## タイトル案','1. 【経緯から丁寧に解説】本能寺の変 ― 光秀はどんな立場で、どの道を通って京都へ来たのか','2. 約1万3千 対 側近20〜150人？ 本能寺の変を国土地理院の地形データで読む','3. 本能寺の変 20.7kmの道のり ― 老ノ坂を越えた行軍を3D地形で検証\n',
'## 概要欄(そのまま貼り付け用)\n','```','1582年(天正10年)6月2日、本能寺の変。明智光秀とはどんな人物で、1582年の春から5月にかけて何があったのか。そして6月1日の夜、亀山城から京都へどんな地形を越えたのか。経緯を丁寧にたどり、国土地理院の標高データと、道路データに沿った経路で、距離・標高・所要時間を確かめます。後半では、史料の読み方と、動機をめぐる諸説(怨恨・野望・突発・朝廷関与・足利義昭・四国など)を、根拠と反論とともに比べます。山崎の戦いなどその後の出来事は、別の動画で扱います。','','わかっていること(史料の概要)と、わからないこと(動機・兵数・最期の様子の詳細)を分けて紹介しています。画面の軍勢・包囲・炎は、史実の再現ではなく説明用の模式表現です。','','■ チャプター']
L+=[f'{ts(t)} {n}' for n,t in ch]
L+=['','■ 出典・クレジット','・地形・写真:国土地理院 地理院タイル(標高 dem_png・オルソ画像 ort・陰影起伏図 hillshademap)を加工して作成 https://maps.gsi.go.jp/development/ichiran.html','・座標:国土地理院 住所検索API','・歴史の概要:Wikipedia(日本語版)「本能寺の変」「明智光秀」「本能寺」「亀山城 (丹波国)」「老ノ坂峠」(CC BY-SA 4.0)の内容を参照し、自作の文章に要約','・肖像画・錦絵:Wikimedia Commons(パブリックドメイン表示)','  織田信長像(長興寺蔵・狩野宗秀筆) / 明智光秀像(本徳寺蔵) / 織田信忠像(総見寺蔵) / 豊臣秀吉像(高台寺蔵) / 徳川家康像(大阪城天守閣蔵・狩野探幽筆) / 錦絵「本能寺焼討之図」(楊斎延一・1896年・名古屋市蔵)','・音声:VOICEVOX:四国めたん','・イメージ画像:ChatGPTによる生成画像(錦絵風)。史実の再現ではありません','・音楽:魔王魂(https://maou.audio/) 民族26 / 民族06 / ピアノ36 / 民族30 / ピアノ12 / ピアノ40(作曲:森田交一。音量調整・場面に合わせた切り替えを行っています)','・制作:Blender、FFmpeg ほか','','■ 注意','・地形と空中写真は現代のもので、3D場面では高さを2倍に強調しています。位置図の地名は町名レベルの概略位置です。1582年当時の地形・河道・市街とは異なります。','・経路は地点を直線で結んだ模式で、実際の街道ではありません。所要時間は仮定の速度による試算です。','・一次史料(信長公記など)の直接校訂は行っていません。','```','','## タグ案','本能寺の変, 明智光秀, 織田信長, 戦国時代, 日本史, 歴史解説, 地形, 3D, 国土地理院, 老ノ坂, 京都, 亀岡, 天正10年, VOICEVOX\n',
'## 投稿前チェック(自分で確認が必要)','- [ ] VOICEVOX:四国めたん の最新規約(動画内+概要欄のクレジットは対応済み)','- [ ] BGM(魔王魂):最新の利用規約を確認(規約は「音楽：魔王魂」の著作表記が必要。概要欄で可)','- [ ] 肖像画・錦絵:Commons各ページのPD表示(国により制限があり得る)。収益化する場合は特に再確認','- [ ] Wikipedia記載の事実を、必要なら一次史料・研究書で確認(動画内の数字: 約1万3千、午前4時ごろ、側近20〜160人、各年の出来事。記事自体が出典不足を指摘している箇所あり)','- [ ] YouTubeの「改変または合成されたコンテンツ」の開示設問に回答(合成音声・生成ではなく3D描画だが、設問文を読んで判断)','- [ ] 字幕: out/hn_subtitles.srt をアップロード(日本語)','- [x] サムネイル: out/thumbnail_A.jpg(推奨)、out/thumbnail_B.jpg(1280x720・JPEG)']
(ROOT/'out'/'youtube_description.md').write_text('\n'.join(L)+'\n',encoding='utf8');print('\n'.join(L[:12]))
